task.en:
Is memory allocated when an array is declared? Do the elements in the array have default values? What happens when the following code is executed?
```cpp
int numbers[30];
cout << "numbers[0] is " << numbers[0] << endl;
cout << "numbers[29] is " << numbers[29] << endl;
cout << "numbers[30] is " << numbers[30] << endl;
```

example.code:
#include <iostream>

int main() {
    // Partial initialization: remaining 3 elements become 0.0
    double partialList[5] = {1.9, 2.9};

    // Implicit size deduction: size is inferred as 4
    int implicitList[] = {10, 20, 30, 40};
    const int implicitSize = sizeof(implicitList) / sizeof(implicitList[0]);

    std::cout << "partialList: ";
    for (int i = 0; i < 5; ++i) {
        std::cout << partialList[i] << " ";
    }
    std::cout << "\n";

    std::cout << "implicitList (size " << implicitSize << "): ";
    for (int i = 0; i < implicitSize; ++i) {
        std::cout << implicitList[i] << " ";
    }
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <string>

int main() {
    const int SIZE = 6;
    int list[SIZE] = {1, 5, 3, 4, 5, 2};

    // 1. Finding max and smallest index of max
    int maxVal = list[0];
    int indexOfMax = 0;
    for (int i = 1; i < SIZE; ++i) {
        if (list[i] > maxVal) {
            maxVal = list[i];
            indexOfMax = i;
        }
    }
    std::cout << "Max: " << maxVal << " at index " << indexOfMax << "\n";

    // 2. Left shift by 1 position with wrap-around
    int temp = list[0];
    for (int i = 1; i < SIZE; ++i) {
        list[i - 1] = list[i];
    }
    list[SIZE - 1] = temp;

    std::cout << "Shifted: ";
    for (int i = 0; i < SIZE; ++i) {
        std::cout << list[i] << " ";
    }
    std::cout << "\n";

    // 3. Lookup table simplification
    std::string months[] = {"Jan", "Feb", "Mar", "Apr", "May", "Jun",
                            "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"};
    int monthNumber = 5;
    std::cout << "Month " << monthNumber << " is " << months[monthNumber - 1] << "\n";

    return 0;
}
